-- 뉴스폭탄 홈페이지 아래 로고 띠: 경기도 28개 시 (누르면 각 시청 홈페이지가 새 창으로 열린다)
--   Supabase SQL 에디터에서 1회 실행. 여러 번 실행해도 같은 결과다 (로고 띠만 덮어쓴다)
--   이미지는 각 시의 공식 로고(CI)를 가로 420×192 흰 바탕으로 맞춘 것이다 (public/sites/newstoday/strip/*.png). 파일 이름이 같아서 이 SQL 을 다시 실행하지 않아도 새 로고로 바뀐다
update public.outlets
set site = jsonb_set(coalesce(site, '{}'::jsonb), '{logoStrip}', '{"title": "경기도 시", "speed": "normal", "items": [{"name": "고양시", "img": "/sites/newstoday/strip/goyang.png", "url": "https://www.goyang.go.kr"}, {"name": "과천시", "img": "/sites/newstoday/strip/gwacheon.png", "url": "https://www.gccity.go.kr"}, {"name": "광명시", "img": "/sites/newstoday/strip/gwangmyeong.png", "url": "https://www.gm.go.kr"}, {"name": "광주시", "img": "/sites/newstoday/strip/gwangju.png", "url": "https://www.gjcity.go.kr"}, {"name": "구리시", "img": "/sites/newstoday/strip/guri.png", "url": "https://www.guri.go.kr"}, {"name": "군포시", "img": "/sites/newstoday/strip/gunpo.png", "url": "https://www.gunpo.go.kr"}, {"name": "김포시", "img": "/sites/newstoday/strip/gimpo.png", "url": "https://www.gimpo.go.kr"}, {"name": "남양주시", "img": "/sites/newstoday/strip/namyangju.png", "url": "https://www.nyj.go.kr"}, {"name": "동두천시", "img": "/sites/newstoday/strip/dongducheon.png", "url": "https://www.ddc.go.kr"}, {"name": "부천시", "img": "/sites/newstoday/strip/bucheon.png", "url": "https://www.bucheon.go.kr"}, {"name": "성남시", "img": "/sites/newstoday/strip/seongnam.png", "url": "https://www.seongnam.go.kr"}, {"name": "수원시", "img": "/sites/newstoday/strip/suwon.png", "url": "https://www.suwon.go.kr"}, {"name": "시흥시", "img": "/sites/newstoday/strip/siheung.png", "url": "https://www.siheung.go.kr"}, {"name": "안산시", "img": "/sites/newstoday/strip/ansan.png", "url": "https://www.ansan.go.kr"}, {"name": "안성시", "img": "/sites/newstoday/strip/anseong.png", "url": "https://www.anseong.go.kr"}, {"name": "안양시", "img": "/sites/newstoday/strip/anyang.png", "url": "https://www.anyang.go.kr"}, {"name": "양주시", "img": "/sites/newstoday/strip/yangju.png", "url": "https://www.yangju.go.kr"}, {"name": "여주시", "img": "/sites/newstoday/strip/yeoju.png", "url": "https://www.yeoju.go.kr"}, {"name": "오산시", "img": "/sites/newstoday/strip/osan.png", "url": "https://www.osan.go.kr"}, {"name": "용인시", "img": "/sites/newstoday/strip/yongin.png", "url": "https://www.yongin.go.kr"}, {"name": "의왕시", "img": "/sites/newstoday/strip/uiwang.png", "url": "https://www.uiwang.go.kr"}, {"name": "의정부시", "img": "/sites/newstoday/strip/uijeongbu.png", "url": "https://www.ui4u.go.kr"}, {"name": "이천시", "img": "/sites/newstoday/strip/icheon.png", "url": "https://www.icheon.go.kr"}, {"name": "파주시", "img": "/sites/newstoday/strip/paju.png", "url": "https://www.paju.go.kr"}, {"name": "평택시", "img": "/sites/newstoday/strip/pyeongtaek.png", "url": "https://www.pyeongtaek.go.kr"}, {"name": "포천시", "img": "/sites/newstoday/strip/pocheon.png", "url": "https://www.pocheon.go.kr"}, {"name": "하남시", "img": "/sites/newstoday/strip/hanam.png", "url": "https://www.hanam.go.kr"}, {"name": "화성시", "img": "/sites/newstoday/strip/hwaseong.png", "url": "https://www.hscity.go.kr"}]}'::jsonb, true)
where domain = 'newstoday.ai.kr';

select name, domain, jsonb_array_length(site->'logoStrip'->'items') as 로고_수 from public.outlets where domain = 'newstoday.ai.kr';
